int watcher_log_header(char *buf, size_t size)
{
    return snprintf(buf, size, "meal,waiting,test,feeder_online,feed_reply,plan");
}

int watcher_log_row(const watcher_state_t *s, char *buf, size_t size)
{
    const tlg_agent_t *a = &s->agent;
    int n = snprintf(buf, size, "%s,%s,%s,%s,%s,", V_MEAL[s->in.meal], V_WAITING[s->in.waiting], V_TEST[s->in.test], V_FEEDER_ONLINE[s->in.feeder_online], V_FEED_REPLY[s->in.feed_reply]);
    if (n < 0 || (size_t)n >= size) return n;
    if (!a->acted_ok || a->plan_len == 0)
        return n + snprintf(buf + n, size - (size_t)n, "%s", a->acted_ok ? "nothing" : "-");
    for (int i = 0; i < a->plan_len; i++) {
        int w = snprintf(buf + n, size - (size_t)n, "%s%s", i ? "+" : "", watcher_domain.actions[a->plan[i]].name);
        if (w < 0 || (size_t)(n + w) >= size) return n + w;
        n += w;
    }
    return n;
}

int watcher_status_json(const watcher_state_t *s, char *buf, size_t size)
{
    const tlg_agent_t *a = &s->agent;
    int n = snprintf(buf, size, "{\"meal\":\"%s\",\"waiting\":\"%s\",\"test\":\"%s\",\"feeder_online\":\"%s\",\"feed_reply\":\"%s\",\"plan\":\"", V_MEAL[s->in.meal], V_WAITING[s->in.waiting], V_TEST[s->in.test], V_FEEDER_ONLINE[s->in.feeder_online], V_FEED_REPLY[s->in.feed_reply]);
    if (n < 0 || (size_t)n >= size) return -1;
    if (!a->acted_ok || a->plan_len == 0)
        n += snprintf(buf + n, size - (size_t)n, "%s", a->acted_ok ? "nothing" : "-");
    for (int i = 0; a->acted_ok && i < a->plan_len && (size_t)n < size; i++)
        n += snprintf(buf + n, size - (size_t)n, "%s%s", i ? " " : "", watcher_domain.actions[a->plan[i]].name);
    if ((size_t)n >= size) return -1;
    n += snprintf(buf + n, size - (size_t)n, "\"}");
    return (size_t)n < size ? n : -1;
}

